#define SAMPLES 64

float noise(vec2 uv, float time, float coeff)
{
    float t = coeff * sin(time);
    float waves = sin((uv.x + uv.y) * t);
    return waves;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.yy;
    float t = iResolution.y / 16.0;
    vec2 tuv = t * uv;
    uv += vec2(-8.0 + 16.0, 1.0) * iMouse.x / iResolution.x;
    uv /= 0.1 * abs(sin(0.1 + iTime * 0.25)) * t;
    float waves = 0.0;
    for( int i = 1; i < SAMPLES; i++ )
    {
        waves += clamp(noise(
            uv * mat2(vec2(sin(tuv.x)), vec2(sin(tuv.y))),
            iTime + float(i),
            41111111.0
        ), 0.0, 1.4 / float(SAMPLES)); // 1.4 instead of 1.0 for contrast
    }
    vec3 col = mix(vec3(0.0, 0.6, 0.4), vec3(0.8, 0.0, 0.2), waves);
    fragColor = vec4(col, 1.0);
}
